import sys

def find_sequence(n):
    if n == 1:
        return "YES\n1"
    if n == 2 or n == 3:
        return "NO"

    # For n >= 4, we can always find a valid sequence
    sequence = [0] * n
    for i in range(n):
        if i == 0:
            sequence[i] = 1
        elif i == 1:
            sequence[i] = 3
        elif i == 2:
            sequence[i] = 2
        else:
            sequence[i] = i + 1

    # Adjust the sequence to ensure the prefix product sequence is [0, 1, ..., n - 1]
    for i in range(n):
        sequence[i] = (sequence[i] - 1) % n + 1

    return "YES\n" + "\n".join(map(str, sequence))

